-- Deal step 6: apply the result to the game tables
-- Generated by scripts/generate/generate.mjs from shared/deal/ (workstream B). Don't edit by hand.

INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_' || LeaderType, 'KIND_TRAIT' FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1));
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly) SELECT 'TRAIT_LSHUF_' || x.LeaderType, (SELECT lx.AbilityName FROM LShufWork_L lx WHERE lx.LeaderType = x.LeaderType), 'LOC_LSHUF_TRAIT_DEALT_DESCRIPTION', 1
  FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1)) x WHERE 'TRAIT_LSHUF_' || x.LeaderType IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_PERSONA_' || LeaderType, 'KIND_TRAIT' FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1) UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL);
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly) SELECT 'TRAIT_LSHUF_PERSONA_' || x.LeaderType, NULL, NULL, 1
  FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1) UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL) x WHERE 'TRAIT_LSHUF_PERSONA_' || x.LeaderType IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_EQUAL_ACTIONS', 'KIND_TRAIT' WHERE EXISTS (SELECT 1 FROM LShufResultAttributes WHERE TraitType = 'TRAIT_LSHUF_EQUAL_ACTIONS');
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly) SELECT 'TRAIT_LSHUF_EQUAL_ACTIONS', NULL, NULL, 1
  WHERE EXISTS (SELECT 1 FROM LShufResultAttributes WHERE TraitType = 'TRAIT_LSHUF_EQUAL_ACTIONS') AND 'TRAIT_LSHUF_EQUAL_ACTIONS' IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT DISTINCT tm.ModifierId, 'TRAIT_LSHUF_EQUAL_ACTIONS' FROM TraitModifiers tm JOIN Modifiers m ON m.ModifierId = tm.ModifierId
  JOIN DynamicModifiers d ON d.ModifierType = m.ModifierType
  WHERE tm.TraitType IN (SELECT TraitType FROM LShufAttributeTraits) AND d.EffectType = 'EFFECT_DIPLOMACY_GRANT_DIPLOMATIC_ACTION'
    AND 'TRAIT_LSHUF_EQUAL_ACTIONS' IN (SELECT TraitType FROM Traits);

INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_EXTRA' || Copy || '_' || TraitType, 'KIND_TRAIT' FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0)
  WHERE TraitType IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly) SELECT 'TRAIT_LSHUF_EXTRA' || Copy || '_' || TraitType, NULL, NULL, 1
  FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0) WHERE 'TRAIT_LSHUF_EXTRA' || Copy || '_' || TraitType IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO Modifiers (ModifierId, ModifierType, NewOnly, OwnerRequirementSetId, OwnerStackLimit, Permanent, RunOnce,
    SubjectRequirementSetId, SubjectStackLimit)
  SELECT 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId, p.ModifierType, p.NewOnly, p.OwnerRequirementSetId, p.OwnerStackLimit, p.Permanent,
    p.RunOnce, p.SubjectRequirementSetId, p.SubjectStackLimit FROM (SELECT x.Copy AS Copy, x.TraitType AS TraitType, m.* FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0) x
    JOIN TraitModifiers tm ON tm.TraitType = x.TraitType JOIN Modifiers m ON m.ModifierId = tm.ModifierId
    JOIN DynamicModifiers d ON d.ModifierType = m.ModifierType WHERE d.EffectType <> 'EFFECT_DIPLOMACY_GRANT_DIPLOMATIC_ACTION') p;
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Extra, SecondExtra, Type, Value)
  SELECT 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId, a.Name, a.Extra, a.SecondExtra, a.Type, a.Value FROM (SELECT x.Copy AS Copy, x.TraitType AS TraitType, m.* FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0) x
    JOIN TraitModifiers tm ON tm.TraitType = x.TraitType JOIN Modifiers m ON m.ModifierId = tm.ModifierId
    JOIN DynamicModifiers d ON d.ModifierType = m.ModifierType WHERE d.EffectType <> 'EFFECT_DIPLOMACY_GRANT_DIPLOMATIC_ACTION') p
  JOIN ModifierArguments a ON a.ModifierId = p.ModifierId
  WHERE 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId, 'TRAIT_LSHUF_EXTRA' || p.Copy || '_' || p.TraitType FROM (SELECT x.Copy AS Copy, x.TraitType AS TraitType, m.* FROM (SELECT DISTINCT Copy, TraitType FROM LShufResultAttributes WHERE Copy > 0) x
    JOIN TraitModifiers tm ON tm.TraitType = x.TraitType JOIN Modifiers m ON m.ModifierId = tm.ModifierId
    JOIN DynamicModifiers d ON d.ModifierType = m.ModifierType WHERE d.EffectType <> 'EFFECT_DIPLOMACY_GRANT_DIPLOMATIC_ACTION') p
  WHERE 'LSHUF_EXTRA' || p.Copy || '__' || p.ModifierId IN (SELECT ModifierId FROM Modifiers)
    AND 'TRAIT_LSHUF_EXTRA' || p.Copy || '_' || p.TraitType IN (SELECT TraitType FROM Traits);

CREATE TABLE IF NOT EXISTS LShufWork_Copy (Receiver TEXT, ModifierId TEXT, PRIMARY KEY (Receiver, ModifierId));
DELETE FROM LShufWork_Copy;
INSERT OR IGNORE INTO LShufWork_Copy (Receiver, ModifierId) SELECT p.LeaderType, tm.ModifierId FROM LShufResultPieces p JOIN TraitModifiers tm ON tm.TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = p.FromLeaderType)
  WHERE p.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1)) AND p.Kind = 'whole' AND tm.ModifierId NOT IN (SELECT mm.ModifierId FROM LShufMappingModifiers mm JOIN LShufMapping m ON m.PieceId = mm.PieceId
      WHERE m.LeaderType = p.FromLeaderType AND (m.Kind = 'agenda' OR mm.Role = 'agenda'));
INSERT OR IGNORE INTO LShufWork_Copy (Receiver, ModifierId) SELECT p.LeaderType, mm.ModifierId FROM LShufResultPieces p JOIN LShufMappingModifiers mm ON mm.PieceId = p.PieceId
  WHERE p.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1)) AND p.Kind = 'bullet' AND mm.Role IN ('effect', 'hidden')
    AND mm.ModifierId IN (SELECT tm.ModifierId FROM TraitModifiers tm WHERE tm.TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = p.FromLeaderType));
INSERT OR IGNORE INTO LShufWork_Copy (Receiver, ModifierId) SELECT p.LeaderType, tm.ModifierId FROM LShufResultPieces p JOIN TraitModifiers tm ON tm.TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = p.FromLeaderType)
  WHERE p.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1)) AND p.Kind = 'remainder' AND tm.ModifierId NOT IN (SELECT mm.ModifierId FROM LShufMappingModifiers mm JOIN LShufMapping m ON m.PieceId = mm.PieceId
      WHERE m.LeaderType = p.FromLeaderType AND ((m.Kind = 'bullet' AND COALESCE(m.Movable, 1) = 1) OR m.Kind = 'agenda'));
DELETE FROM LShufWork_Copy WHERE ModifierId NOT IN (SELECT ModifierId FROM Modifiers);

INSERT OR IGNORE INTO Modifiers (ModifierId, ModifierType, NewOnly, OwnerRequirementSetId, OwnerStackLimit, Permanent, RunOnce,
    SubjectRequirementSetId, SubjectStackLimit)
  SELECT 'LSHUF_' || c.Receiver || '__' || m.ModifierId, m.ModifierType, m.NewOnly, m.OwnerRequirementSetId, m.OwnerStackLimit, m.Permanent, m.RunOnce,
    m.SubjectRequirementSetId, m.SubjectStackLimit FROM LShufWork_Copy c JOIN Modifiers m ON m.ModifierId = c.ModifierId;
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Extra, SecondExtra, Type, Value)
  SELECT 'LSHUF_' || c.Receiver || '__' || a.ModifierId, a.Name, a.Extra, a.SecondExtra, a.Type, a.Value
  FROM LShufWork_Copy c JOIN ModifierArguments a ON a.ModifierId = c.ModifierId
  WHERE 'LSHUF_' || c.Receiver || '__' || a.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO ModifierStrings (Context, ModifierId, Text)
  SELECT s.Context, 'LSHUF_' || c.Receiver || '__' || s.ModifierId, s.Text
  FROM LShufWork_Copy c JOIN ModifierStrings s ON s.ModifierId = c.ModifierId
  WHERE 'LSHUF_' || c.Receiver || '__' || s.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT 'LSHUF_' || c.Receiver || '__' || c.ModifierId, 'TRAIT_LSHUF_' || c.Receiver FROM LShufWork_Copy c
  WHERE 'LSHUF_' || c.Receiver || '__' || c.ModifierId IN (SELECT ModifierId FROM Modifiers)
    AND 'TRAIT_LSHUF_' || c.Receiver IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT tm.ModifierId, 'TRAIT_LSHUF_PERSONA_' || x.LeaderType FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1) UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL) x
  JOIN LShufWork_L l ON l.LeaderType = x.LeaderType
  JOIN TraitModifiers tm ON tm.TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = l.PersonaFrom)
  WHERE tm.ModifierId IN (SELECT mm.ModifierId FROM LShufMappingModifiers mm JOIN LShufMapping m ON m.PieceId = mm.PieceId
      WHERE m.LeaderType = l.PersonaFrom AND (m.Kind = 'agenda' OR mm.Role = 'agenda')) AND 'TRAIT_LSHUF_PERSONA_' || x.LeaderType IN (SELECT TraitType FROM Traits);

CREATE TABLE IF NOT EXISTS LShufWork_AiSrc (LeaderType TEXT, Trait TEXT, PRIMARY KEY (LeaderType, Trait));
DELETE FROM LShufWork_AiSrc;
INSERT OR IGNORE INTO LShufWork_AiSrc (LeaderType, Trait) SELECT LeaderType, Trait FROM (SELECT DISTINCT p.LeaderType, (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = p.FromLeaderType) AS Trait FROM LShufResultPieces p
    WHERE p.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1))) WHERE Trait IS NOT NULL;
INSERT OR IGNORE INTO AiListTypes (ListType) SELECT 'LSHUF_' || s.LeaderType || '__' || a.ListType FROM LShufWork_AiSrc s JOIN AiLists a ON a.LeaderType = s.Trait;
INSERT OR IGNORE INTO AiLists (LeaderType, ListType, MaxDifficulty, MinDifficulty, System)
  SELECT 'TRAIT_LSHUF_' || s.LeaderType, 'LSHUF_' || s.LeaderType || '__' || a.ListType, a.MaxDifficulty, a.MinDifficulty, a.System
  FROM LShufWork_AiSrc s JOIN AiLists a ON a.LeaderType = s.Trait WHERE 'LSHUF_' || s.LeaderType || '__' || a.ListType IN (SELECT ListType FROM AiListTypes);
INSERT OR IGNORE INTO AiFavoredItems (Favored, Item, ListType, StringVal, Value, MaxDifficulty, MinDifficulty, TooltipString)
  SELECT f.Favored, f.Item, 'LSHUF_' || s.LeaderType || '__' || a.ListType, f.StringVal, f.Value, f.MaxDifficulty, f.MinDifficulty, f.TooltipString
  FROM LShufWork_AiSrc s JOIN AiLists a ON a.LeaderType = s.Trait JOIN AiFavoredItems f ON f.ListType = a.ListType
  WHERE 'LSHUF_' || s.LeaderType || '__' || a.ListType IN (SELECT ListType FROM AiListTypes);

DELETE FROM LeaderTraits WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 OR ((SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL))
  AND TraitType = (SELECT lx.Ability FROM LShufWork_L lx WHERE lx.LeaderType = LeaderTraits.LeaderType);
DELETE FROM LeaderTraits WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InT = 1 OR ((SELECT OffT FROM LShufWork_Cfg) = 1 AND RT IS NULL)) AND TraitType IN (SELECT TraitType FROM LShufAttributeTraits);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT d.LeaderType, l.Ability FROM LShufWork_Donor d
  JOIN LShufWork_L l ON l.LeaderType = d.Donor
  WHERE d.Axis = 'A' AND (SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1 AND l.Ability IN (SELECT TraitType FROM Traits)
    AND d.LeaderType NOT IN (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1));
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT LeaderType, 'TRAIT_LSHUF_' || LeaderType FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1))
  WHERE 'TRAIT_LSHUF_' || LeaderType IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT LeaderType, 'TRAIT_LSHUF_PERSONA_' || LeaderType FROM (SELECT LeaderType FROM LShufWork_L WHERE InA = 1 AND (NOT ((SELECT IsWhole FROM LShufWork_Cfg) = 1 AND (SELECT Follows FROM LShufWork_Cfg) = 1)
  OR (SELECT b.PersonaPick FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType) IS NOT NULL OR COALESCE((SELECT b.BulletBuild FROM LShufWork_Build b WHERE b.OK = 1 AND b.Leader = LeaderType), 0) = 1) UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffA FROM LShufWork_Cfg) = 1 AND RA IS NULL)
  WHERE 'TRAIT_LSHUF_PERSONA_' || LeaderType IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT r.LeaderType, r.TraitType FROM LShufResultAttributes r
  WHERE r.Copy = 0 AND r.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InT = 1 OR ((SELECT OffT FROM LShufWork_Cfg) = 1 AND RT IS NULL)) AND r.TraitType IN (SELECT TraitType FROM Traits)
    AND r.LeaderType IN (SELECT LeaderType FROM Leaders);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT r.LeaderType, 'TRAIT_LSHUF_EXTRA' || r.Copy || '_' || r.TraitType
  FROM LShufResultAttributes r
  WHERE r.Copy > 0 AND r.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE InT = 1 OR ((SELECT OffT FROM LShufWork_Cfg) = 1 AND RT IS NULL)) AND 'TRAIT_LSHUF_EXTRA' || r.Copy || '_' || r.TraitType IN (SELECT TraitType FROM Traits)
    AND r.LeaderType IN (SELECT LeaderType FROM Leaders);

UPDATE ProgressionTreeNodeUnlocks SET RequiredTraitType = (SELECT r.ToTraitType FROM LShufResultUnlocks r
    WHERE r.ProgressionTreeNodeType = ProgressionTreeNodeUnlocks.ProgressionTreeNodeType AND r.TargetType = ProgressionTreeNodeUnlocks.TargetType)
  WHERE RequiredTraitType IN (SELECT Ability FROM LShufWork_L WHERE Ability IS NOT NULL)
    AND EXISTS (SELECT 1 FROM LShufResultUnlocks r WHERE r.ProgressionTreeNodeType = ProgressionTreeNodeUnlocks.ProgressionTreeNodeType
    AND r.TargetType = ProgressionTreeNodeUnlocks.TargetType AND r.FromTraitType = ProgressionTreeNodeUnlocks.RequiredTraitType AND r.ToTraitType IS NOT NULL
      AND r.ToTraitType <> r.FromTraitType AND r.ToTraitType IN (SELECT TraitType FROM Traits));

CREATE TABLE IF NOT EXISTS LShufWork_UnitTrait (Owner TEXT, TraitType TEXT, ToLeader TEXT, PRIMARY KEY (Owner, TraitType));
DELETE FROM LShufWork_UnitTrait;
INSERT OR IGNORE INTO LShufWork_UnitTrait (Owner, TraitType, ToLeader)
  SELECT l.LeaderType, u.TraitType, r.ToLeaderType FROM LShufResultUnlocks r
  JOIN LShufWork_L l ON l.Ability = r.FromTraitType
  JOIN Units u ON u.UnitType = r.TargetType
  JOIN LeaderTraits lt ON lt.LeaderType = l.LeaderType AND lt.TraitType = u.TraitType
  WHERE u.TraitType <> l.Ability AND (r.ToLeaderType IS NULL OR r.ToLeaderType <> l.LeaderType);
DELETE FROM LeaderTraits WHERE EXISTS (SELECT 1 FROM LShufWork_UnitTrait w
  WHERE w.Owner = LeaderTraits.LeaderType AND w.TraitType = LeaderTraits.TraitType);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT ToLeader, TraitType FROM LShufWork_UnitTrait
  WHERE ToLeader IN (SELECT LeaderType FROM Leaders) AND TraitType IN (SELECT TraitType FROM Traits);

INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_IBN_WILDCARD', 'KIND_TRAIT' WHERE EXISTS (SELECT 1 FROM LShufResultUnlocks r WHERE r.FromTraitType = 'TRAIT_LEADER_IBN_BATTUTA_ABILITY' AND r.ProgressionTreeNodeType = 'NODE_ATTRIBUTE_EXPANSIONIST_LEGEND_IBN_BATTUTA_L2' AND (r.ToLeaderType IS NULL OR r.ToLeaderType <> 'LEADER_IBN_BATTUTA'))
  AND EXISTS (SELECT 1 FROM RequirementSetRequirements WHERE RequirementId = 'REQ_STORY_LEADER_IBN_BATTUTA' AND RequirementSetId IN ('REQSET_ATTRIBUTE_79A_NARRATIVE', 'REQSET_ATTRIBUTE_79A_NARRATIVE_REQUISITE'));
INSERT OR IGNORE INTO Traits (TraitType, InternalOnly) SELECT 'TRAIT_LSHUF_IBN_WILDCARD', 1 WHERE 'TRAIT_LSHUF_IBN_WILDCARD' IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO Requirements (RequirementId, RequirementType)
  SELECT 'REQ_LSHUF_IBN_WILDCARD', 'REQUIREMENT_PLAYER_HAS_CIVILIZATION_OR_LEADER_TRAIT' WHERE 'TRAIT_LSHUF_IBN_WILDCARD' IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO RequirementArguments (RequirementId, Name, Value)
  SELECT 'REQ_LSHUF_IBN_WILDCARD', 'TraitType', 'TRAIT_LSHUF_IBN_WILDCARD' WHERE 'REQ_LSHUF_IBN_WILDCARD' IN (SELECT RequirementId FROM Requirements);
UPDATE RequirementSetRequirements SET RequirementId = 'REQ_LSHUF_IBN_WILDCARD'
  WHERE RequirementId = 'REQ_STORY_LEADER_IBN_BATTUTA' AND RequirementSetId IN ('REQSET_ATTRIBUTE_79A_NARRATIVE', 'REQSET_ATTRIBUTE_79A_NARRATIVE_REQUISITE')
    AND 'REQ_LSHUF_IBN_WILDCARD' IN (SELECT RequirementId FROM Requirements);
INSERT OR IGNORE INTO LeaderTraits (LeaderType, TraitType) SELECT (SELECT r.ToLeaderType FROM LShufResultUnlocks r WHERE r.FromTraitType = 'TRAIT_LEADER_IBN_BATTUTA_ABILITY' AND r.ProgressionTreeNodeType = 'NODE_ATTRIBUTE_EXPANSIONIST_LEGEND_IBN_BATTUTA_L2' LIMIT 1), 'TRAIT_LSHUF_IBN_WILDCARD'
  WHERE EXISTS (SELECT 1 FROM LShufResultUnlocks r WHERE r.FromTraitType = 'TRAIT_LEADER_IBN_BATTUTA_ABILITY' AND r.ProgressionTreeNodeType = 'NODE_ATTRIBUTE_EXPANSIONIST_LEGEND_IBN_BATTUTA_L2' AND (r.ToLeaderType IS NULL OR r.ToLeaderType <> 'LEADER_IBN_BATTUTA')) AND (SELECT r.ToLeaderType FROM LShufResultUnlocks r WHERE r.FromTraitType = 'TRAIT_LEADER_IBN_BATTUTA_ABILITY' AND r.ProgressionTreeNodeType = 'NODE_ATTRIBUTE_EXPANSIONIST_LEGEND_IBN_BATTUTA_L2' LIMIT 1) IN (SELECT LeaderType FROM Leaders) AND 'TRAIT_LSHUF_IBN_WILDCARD' IN (SELECT TraitType FROM Traits);

DELETE FROM StartBiasBiomes WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasBiomes WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasBiomes (CivilizationType, LeaderType, BiomeType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.TargetType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasBiomes' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations)) AND r.TargetType IN (SELECT BiomeType FROM Biomes);
DELETE FROM StartBiasTerrains WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasTerrains WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasTerrains (CivilizationType, LeaderType, TerrainType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.TargetType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasTerrains' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations)) AND r.TargetType IN (SELECT TerrainType FROM Terrains);
DELETE FROM StartBiasAdjacentToCoasts WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasAdjacentToCoasts WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasAdjacentToCoasts (CivilizationType, LeaderType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasAdjacentToCoasts' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations));
DELETE FROM StartBiasFeatureClasses WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasFeatureClasses WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasFeatureClasses (CivilizationType, LeaderType, FeatureClassType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.TargetType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasFeatureClasses' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations)) AND r.TargetType IN (SELECT FeatureClassType FROM FeatureClasses);
DELETE FROM StartBiasRivers WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasRivers WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasRivers (CivilizationType, LeaderType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasRivers' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations));
DELETE FROM StartBiasLakes WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasLakes WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasLakes (CivilizationType, LeaderType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasLakes' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations));
DELETE FROM StartBiasNaturalWonders WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasNaturalWonders WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasNaturalWonders (CivilizationType, LeaderType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasNaturalWonders' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations));
DELETE FROM StartBiasIslands WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasIslands WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasIslands (CivilizationType, LeaderType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasIslands' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations));
DELETE FROM StartBiasResources WHERE LeaderType IN (SELECT LeaderType FROM LShufWork_Pool WHERE Axis = 'B'
    UNION SELECT LeaderType FROM LShufWork_L WHERE (SELECT OffB FROM LShufWork_Cfg) = 1 AND RB IS NULL);
DELETE FROM StartBiasResources WHERE LeaderType IS NULL AND ((SELECT OffB FROM LShufWork_Cfg) = 1 OR ((SELECT Dealt FROM LShufWork_Axis WHERE Axis = 'B') = 1 AND CivilizationType IN (SELECT CivilizationType FROM LShufWork_Civ WHERE (SELECT RollBiases FROM LShufWork_Cfg) = 1 OR Donor <> CivilizationType)));
INSERT OR IGNORE INTO StartBiasResources (CivilizationType, LeaderType, ResourceType, Score)
  SELECT r.CivilizationType, r.LeaderType, r.TargetType, r.Score FROM LShufResultBiases r
  WHERE r.TableName = 'StartBiasResources' AND r.Origin <> 'shipped'
    AND (r.LeaderType IS NULL OR r.LeaderType IN (SELECT LeaderType FROM Leaders))
    AND (r.CivilizationType IS NULL OR r.CivilizationType IN (SELECT CivilizationType FROM Civilizations)) AND r.TargetType IN (SELECT ResourceType FROM Resources);
CREATE TABLE IF NOT EXISTS LShufWork_LCP (Civilization TEXT, Leader TEXT, Priority INTEGER);
DELETE FROM LShufWork_LCP;
INSERT INTO LShufWork_LCP (Civilization, Leader, Priority) SELECT Civilization, Leader, Priority FROM LeaderCivPriorities
  WHERE Leader IN (SELECT PersonaFrom FROM LShufWork_L);
DELETE FROM LeaderCivPriorities WHERE Leader IN (SELECT LeaderType FROM LShufWork_L WHERE PersonaFrom IS NOT NULL AND PersonaFrom <> LeaderType);
INSERT OR IGNORE INTO LeaderCivPriorities (Civilization, Leader, Priority)
  SELECT c.Civilization, l.LeaderType, c.Priority FROM LShufWork_L l JOIN LShufWork_LCP c ON c.Leader = l.PersonaFrom
  WHERE l.LeaderType IN (SELECT LeaderType FROM LShufWork_L WHERE PersonaFrom IS NOT NULL AND PersonaFrom <> LeaderType) AND c.Civilization IN (SELECT CivilizationType FROM Civilizations);

-- Civilization builds (CONTRACTS 14): ability swaps, then the moved uniques on a trait of the builder civ's own.
CREATE TABLE IF NOT EXISTS LShufWork_CivTraitSwap (Civ TEXT, OldTrait TEXT, NewTrait TEXT, PRIMARY KEY (Civ, OldTrait));
DELETE FROM LShufWork_CivTraitSwap;
INSERT OR IGNORE INTO LShufWork_CivTraitSwap (Civ, OldTrait, NewTrait)
  SELECT r.CivilizationType, i.Ability, s.Ability FROM LShufResultCivPieces r
  JOIN LShufWork_CivInfo i ON i.Civ = r.CivilizationType JOIN LShufWork_CivInfo s ON s.Civ = r.FromCivilization
  WHERE r.Kind = 'ability';
UPDATE CivilizationTraits SET TraitType = (SELECT w.NewTrait FROM LShufWork_CivTraitSwap w
    WHERE w.Civ = CivilizationTraits.CivilizationType AND w.OldTrait = CivilizationTraits.TraitType)
  WHERE EXISTS (SELECT 1 FROM LShufWork_CivTraitSwap w WHERE w.Civ = CivilizationTraits.CivilizationType
    AND w.OldTrait = CivilizationTraits.TraitType AND w.NewTrait IN (SELECT TraitType FROM Traits));
INSERT OR IGNORE INTO Types (Type, Kind) SELECT DISTINCT 'TRAIT_LSHUF_CIV_' || CivilizationType, 'KIND_TRAIT' FROM LShufResultCivPieces
  WHERE Kind IN ('unique', 'civics', 'civic') AND CivilizationType IN (SELECT CivilizationType FROM Civilizations);
INSERT OR IGNORE INTO Traits (TraitType, InternalOnly) SELECT DISTINCT 'TRAIT_LSHUF_CIV_' || CivilizationType, 1 FROM LShufResultCivPieces
  WHERE Kind IN ('unique', 'civics', 'civic') AND 'TRAIT_LSHUF_CIV_' || CivilizationType IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO CivilizationTraits (CivilizationType, TraitType) SELECT DISTINCT CivilizationType, 'TRAIT_LSHUF_CIV_' || CivilizationType
  FROM LShufResultCivPieces WHERE Kind IN ('unique', 'civics', 'civic') AND CivilizationType IN (SELECT CivilizationType FROM Civilizations)
    AND 'TRAIT_LSHUF_CIV_' || CivilizationType IN (SELECT TraitType FROM Traits);
UPDATE Units SET TraitType = (SELECT 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r WHERE r.Kind = 'unique'
    AND (r.PieceId = 'CIVUNQ_' || Units.UnitType OR Units.UnitType LIKE substr(r.PieceId, 8) || '\_%' ESCAPE '\'))
  WHERE EXISTS (SELECT 1 FROM LShufResultCivPieces r WHERE r.Kind = 'unique'
    AND (r.PieceId = 'CIVUNQ_' || Units.UnitType OR Units.UnitType LIKE substr(r.PieceId, 8) || '\_%' ESCAPE '\')
    AND 'TRAIT_LSHUF_CIV_' || r.CivilizationType IN (SELECT TraitType FROM Traits));
UPDATE Improvements SET TraitType = (SELECT 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r WHERE r.Kind = 'unique' AND r.PieceId = 'CIVUNQ_' || ConstructibleType)
  WHERE 'CIVUNQ_' || ConstructibleType IN (SELECT PieceId FROM LShufResultCivPieces WHERE Kind = 'unique') AND (SELECT 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r WHERE r.Kind = 'unique' AND r.PieceId = 'CIVUNQ_' || ConstructibleType) IN (SELECT TraitType FROM Traits);
-- The main-tree nodes that unlock a moved unique (its whole family) ask for the new civ's trait instead of the source's.
UPDATE ProgressionTreeNodeUnlocks SET RequiredTraitType = (SELECT 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r
    JOIN LShufWork_CivInfo s ON s.Civ = r.FromCivilization
    WHERE r.Kind = 'unique' AND s.Base = ProgressionTreeNodeUnlocks.RequiredTraitType
      AND (r.PieceId = 'CIVUNQ_' || ProgressionTreeNodeUnlocks.TargetType
        OR ProgressionTreeNodeUnlocks.TargetType LIKE substr(r.PieceId, 8) || '\_%' ESCAPE '\'))
  WHERE EXISTS (SELECT 1 FROM LShufResultCivPieces r JOIN LShufWork_CivInfo s ON s.Civ = r.FromCivilization
    WHERE r.Kind = 'unique' AND s.Base = ProgressionTreeNodeUnlocks.RequiredTraitType
      AND (r.PieceId = 'CIVUNQ_' || ProgressionTreeNodeUnlocks.TargetType
        OR ProgressionTreeNodeUnlocks.TargetType LIKE substr(r.PieceId, 8) || '\_%' ESCAPE '\')
      AND 'TRAIT_LSHUF_CIV_' || r.CivilizationType IN (SELECT TraitType FROM Traits));
-- Civilization abilities Off for everyone (CONTRACTS 16): every civ's ability trait row goes, except a civ that took one.
DELETE FROM CivilizationTraits WHERE (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_OFF'
  AND TraitType IN (SELECT Ability FROM LShufWork_CivInfo)
  AND CivilizationType NOT IN (SELECT CivilizationType FROM LShufResultCivPieces WHERE Kind = 'ability');
-- Civilization uniques Off for everyone: every unique goes onto a trait no civ holds, except the ones builders took.
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_NONE', 'KIND_TRAIT' WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF';
INSERT OR IGNORE INTO Traits (TraitType, InternalOnly) SELECT 'TRAIT_LSHUF_NONE', 1 WHERE 'TRAIT_LSHUF_NONE' IN (SELECT Type FROM Types);
UPDATE Units SET TraitType = 'TRAIT_LSHUF_NONE'
  WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF' AND 'TRAIT_LSHUF_NONE' IN (SELECT TraitType FROM Traits)
    AND TraitType IN (SELECT Base FROM LShufWork_CivInfo) AND 'CIVUNQ_' || UnitType NOT IN (SELECT PieceId FROM LShufResultCivPieces WHERE Kind = 'unique') AND UnitType NOT IN (SELECT UnitType FROM LShufWork_CivicUnit);
UPDATE Improvements SET TraitType = 'TRAIT_LSHUF_NONE'
  WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF' AND 'TRAIT_LSHUF_NONE' IN (SELECT TraitType FROM Traits)
    AND TraitType IN (SELECT Base FROM LShufWork_CivInfo) AND 'CIVUNQ_' || ConstructibleType NOT IN (SELECT PieceId FROM LShufResultCivPieces WHERE Kind = 'unique') AND ConstructibleType NOT IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\');
-- Unique civics (CONTRACTS 18): every civ that gives its civics (or loses them to Off) gets a trait of its own for
-- its units and main-tree improvements, then its base trait goes to the receiver.
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_CIV_' || Civ, 'KIND_TRAIT' FROM LShufWork_CivInfo WHERE Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL));
INSERT OR IGNORE INTO Traits (TraitType, InternalOnly) SELECT 'TRAIT_LSHUF_CIV_' || Civ, 1 FROM LShufWork_CivInfo
  WHERE Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL)) AND 'TRAIT_LSHUF_CIV_' || Civ IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO CivilizationTraits (CivilizationType, TraitType) SELECT Civ, 'TRAIT_LSHUF_CIV_' || Civ FROM LShufWork_CivInfo
  WHERE Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL)) AND Civ IN (SELECT CivilizationType FROM Civilizations) AND 'TRAIT_LSHUF_CIV_' || Civ IN (SELECT TraitType FROM Traits);
UPDATE Units SET TraitType = (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = TraitType)
  WHERE TraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL))) AND (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = TraitType) IN (SELECT TraitType FROM Traits) AND UnitType NOT IN (SELECT UnitType FROM LShufWork_CivicUnit);
UPDATE Improvements SET TraitType = (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = TraitType)
  WHERE TraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL))) AND (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = TraitType) IN (SELECT TraitType FROM Traits) AND ConstructibleType NOT IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u JOIN ProgressionTreeNodes n
    ON n.ProgressionTreeNodeType = u.ProgressionTreeNodeType WHERE n.ProgressionTree LIKE 'TREE\_CIVICS\_%' ESCAPE '\' AND n.ProgressionTree NOT LIKE '%\_MAIN' ESCAPE '\');
UPDATE ProgressionTreeNodeUnlocks SET RequiredTraitType = (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = RequiredTraitType)
  WHERE RequiredTraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL))) AND (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = RequiredTraitType) IN (SELECT TraitType FROM Traits);
UPDATE ProgressionTreeNodeUnlocks SET NotTraitType = (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = NotTraitType)
  WHERE NotTraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL))) AND (SELECT 'TRAIT_LSHUF_CIV_' || d.Civ FROM LShufWork_CivInfo d WHERE d.Base = NotTraitType) IN (SELECT TraitType FROM Traits);
UPDATE CivilizationTraits SET CivilizationType = (SELECT r.CivilizationType FROM LShufResultCivPieces r JOIN LShufWork_CivInfo d ON d.Civ = r.FromCivilization
    WHERE r.Kind = 'civics' AND d.Base = CivilizationTraits.TraitType AND d.Civ = CivilizationTraits.CivilizationType)
  WHERE (SELECT r.CivilizationType FROM LShufResultCivPieces r JOIN LShufWork_CivInfo d ON d.Civ = r.FromCivilization
    WHERE r.Kind = 'civics' AND d.Base = CivilizationTraits.TraitType AND d.Civ = CivilizationTraits.CivilizationType) IN (SELECT CivilizationType FROM Civilizations);
-- Civilization civics Off for everyone: the base trait of every civ whose civics didn't move goes to nobody.
DELETE FROM CivilizationTraits WHERE (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND TraitType IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT d.Civ FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics')
    OR ((SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF' AND d.Tree IS NOT NULL)))
  AND TraitType NOT IN (SELECT d.Base FROM LShufWork_CivInfo d WHERE d.Civ IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'civics'));
-- Civics in pieces (CONTRACTS 21): a moved civic goes into its new civ's tree as the tree stands after the whole
-- swaps; a civ with no tree of its own (another age's civ, which holds TRAIT_ANACHRONISTIC_CIV) gets it in the age's
-- Test of Time tree, gated on the civ's own trait. Prerequisites that would cross trees go. What the civic unlocks
-- (buildings, improvements, units) goes onto the new civ's own trait, as a taken unique does.
CREATE TABLE IF NOT EXISTS LShufWork_CivFinalTree (Civ TEXT PRIMARY KEY, Tree TEXT);
DELETE FROM LShufWork_CivFinalTree;
INSERT OR IGNORE INTO LShufWork_CivFinalTree (Civ, Tree) SELECT i.Civ, COALESCE(
    (SELECT d.Tree FROM LShufResultCivPieces r JOIN LShufWork_CivInfo d ON d.Civ = r.FromCivilization
      WHERE r.Kind = 'civics' AND r.CivilizationType = i.Civ),
    i.Tree,
    CASE WHEN EXISTS (SELECT 1 FROM CivilizationTraits ct WHERE ct.CivilizationType = i.Civ AND ct.TraitType = 'TRAIT_ANACHRONISTIC_CIV')
      THEN (SELECT MIN(ProgressionTreeType) FROM ProgressionTrees WHERE ProgressionTreeType LIKE 'TREE\_CIVICS\_%\_TEST\_OF\_TIME' ESCAPE '\') END)
  FROM LShufWork_CivInfo i;
CREATE TABLE IF NOT EXISTS LShufWork_CivMoved (Node TEXT PRIMARY KEY, Civ TEXT, Tree TEXT, OwnTrait TEXT);
DELETE FROM LShufWork_CivMoved;
INSERT OR IGNORE INTO LShufWork_CivMoved (Node, Civ, Tree, OwnTrait)
  SELECT substr(r.PieceId, 9), r.CivilizationType, f.Tree, 'TRAIT_LSHUF_CIV_' || r.CivilizationType FROM LShufResultCivPieces r
  JOIN LShufWork_CivFinalTree f ON f.Civ = r.CivilizationType
  WHERE r.Kind = 'civic' AND f.Tree IN (SELECT ProgressionTreeType FROM ProgressionTrees)
    AND substr(r.PieceId, 9) IN (SELECT ProgressionTreeNodeType FROM ProgressionTreeNodes);
UPDATE ProgressionTreeNodes SET ProgressionTree = (SELECT m.Tree FROM LShufWork_CivMoved m WHERE m.Node = ProgressionTreeNodes.ProgressionTreeNodeType)
  WHERE ProgressionTreeNodeType IN (SELECT Node FROM LShufWork_CivMoved);
DELETE FROM ProgressionTreePrereqs WHERE (Node IN (SELECT Node FROM LShufWork_CivMoved) OR PrereqNode IN (SELECT Node FROM LShufWork_CivMoved))
  AND (SELECT a.ProgressionTree FROM ProgressionTreeNodes a WHERE a.ProgressionTreeNodeType = ProgressionTreePrereqs.Node)
    <> (SELECT b.ProgressionTree FROM ProgressionTreeNodes b WHERE b.ProgressionTreeNodeType = ProgressionTreePrereqs.PrereqNode);
INSERT OR IGNORE INTO ProgressionTreeNodeTraits (ProgressionTreeNodeType, RequiredTraitType)
  SELECT m.Node, m.OwnTrait FROM LShufWork_CivMoved m JOIN LShufWork_CivInfo i ON i.Civ = m.Civ
  WHERE i.Tree IS NULL AND m.OwnTrait IN (SELECT TraitType FROM Traits);
UPDATE ProgressionTreeNodeUnlocks SET RequiredTraitType = (SELECT m.OwnTrait FROM LShufWork_CivMoved m WHERE m.Node = ProgressionTreeNodeUnlocks.ProgressionTreeNodeType)
  WHERE ProgressionTreeNodeType IN (SELECT Node FROM LShufWork_CivMoved) AND RequiredTraitType IN (SELECT Base FROM LShufWork_CivInfo)
    AND (SELECT m.OwnTrait FROM LShufWork_CivMoved m WHERE m.Node = ProgressionTreeNodeUnlocks.ProgressionTreeNodeType) IN (SELECT TraitType FROM Traits);
UPDATE Buildings SET TraitType = (SELECT MIN(m.OwnTrait) FROM LShufWork_CivMoved m JOIN ProgressionTreeNodeUnlocks u ON u.ProgressionTreeNodeType = m.Node
    WHERE u.TargetType = Buildings.ConstructibleType)
  WHERE TraitType IN (SELECT Base FROM LShufWork_CivInfo) AND ConstructibleType IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u
    JOIN LShufWork_CivMoved m ON m.Node = u.ProgressionTreeNodeType WHERE m.OwnTrait IN (SELECT TraitType FROM Traits));
UPDATE Improvements SET TraitType = (SELECT MIN(m.OwnTrait) FROM LShufWork_CivMoved m JOIN ProgressionTreeNodeUnlocks u ON u.ProgressionTreeNodeType = m.Node
    WHERE u.TargetType = Improvements.ConstructibleType)
  WHERE TraitType IN (SELECT Base FROM LShufWork_CivInfo) AND ConstructibleType IN (SELECT u.TargetType FROM ProgressionTreeNodeUnlocks u
    JOIN LShufWork_CivMoved m ON m.Node = u.ProgressionTreeNodeType WHERE m.OwnTrait IN (SELECT TraitType FROM Traits));
UPDATE Units SET TraitType = (SELECT MIN(m.OwnTrait) FROM LShufWork_CivMoved m JOIN ProgressionTreeNodeUnlocks u ON u.ProgressionTreeNodeType = m.Node
    WHERE (Units.UnitType = u.TargetType OR Units.UnitType LIKE u.TargetType || '\_%' ESCAPE '\'))
  WHERE TraitType IN (SELECT Base FROM LShufWork_CivInfo) AND EXISTS (SELECT 1 FROM ProgressionTreeNodeUnlocks u
    JOIN LShufWork_CivMoved m ON m.Node = u.ProgressionTreeNodeType WHERE (Units.UnitType = u.TargetType OR Units.UnitType LIKE u.TargetType || '\_%' ESCAPE '\') AND m.OwnTrait IN (SELECT TraitType FROM Traits));
-- A great person tied to a quarter or constructible (CONTRACTS 23 R1) goes onto the trait that now carries it.
UPDATE Units SET TraitType = (SELECT COALESCE((SELECT b.TraitType FROM Buildings b WHERE b.ConstructibleType = g.Anchor),
    (SELECT m.TraitType FROM Improvements m WHERE m.ConstructibleType = g.Anchor),
    (SELECT v.OwnTrait FROM LShufWork_CivMoved v WHERE v.Node = g.Anchor))
  FROM LShufWork_CivicGP g WHERE g.UnitType = Units.UnitType)
  WHERE UnitType IN (SELECT UnitType FROM LShufWork_CivicGP) AND TraitType IN (SELECT Base FROM LShufWork_CivInfo)
    AND (SELECT COALESCE((SELECT b.TraitType FROM Buildings b WHERE b.ConstructibleType = g.Anchor),
    (SELECT m.TraitType FROM Improvements m WHERE m.ConstructibleType = g.Anchor),
    (SELECT v.OwnTrait FROM LShufWork_CivMoved v WHERE v.Node = g.Anchor))
  FROM LShufWork_CivicGP g WHERE g.UnitType = Units.UnitType) LIKE 'TRAIT\_LSHUF\_CIV\_%' ESCAPE '\' AND (SELECT COALESCE((SELECT b.TraitType FROM Buildings b WHERE b.ConstructibleType = g.Anchor),
    (SELECT m.TraitType FROM Improvements m WHERE m.ConstructibleType = g.Anchor),
    (SELECT v.OwnTrait FROM LShufWork_CivMoved v WHERE v.Node = g.Anchor))
  FROM LShufWork_CivicGP g WHERE g.UnitType = Units.UnitType) IN (SELECT TraitType FROM Traits);
UPDATE UniqueQuarters SET TraitType = (SELECT b.TraitType FROM Buildings b WHERE b.ConstructibleType = UniqueQuarters.BuildingType1)
  WHERE (SELECT b.TraitType FROM Buildings b WHERE b.ConstructibleType = UniqueQuarters.BuildingType1) LIKE 'TRAIT\_LSHUF\_CIV\_%' ESCAPE '\'
    AND (SELECT b.TraitType FROM Buildings b WHERE b.ConstructibleType = UniqueQuarters.BuildingType1)
      = (SELECT b.TraitType FROM Buildings b WHERE b.ConstructibleType = UniqueQuarters.BuildingType2);
-- The civics-tree reveal of Exploration and Modern (MOD_REVEAL_CIV_CULTURE_TREE_<CIV>) sits on the ability but asks
-- for the base trait. It moves onto the base trait, which carries the civics (CONTRACTS 18), so the tree opens for
-- whoever holds them: a builder holding only other civs' bonus cards, or a civ whose ability went elsewhere.
CREATE TABLE IF NOT EXISTS LShufWork_CivReveal (ModifierId TEXT PRIMARY KEY, Ability TEXT, Base TEXT);
DELETE FROM LShufWork_CivReveal;
INSERT OR IGNORE INTO LShufWork_CivReveal (ModifierId, Ability, Base)
  SELECT tm.ModifierId, i.Ability, i.Base FROM TraitModifiers tm JOIN LShufWork_CivInfo i ON i.Ability = tm.TraitType
  JOIN Modifiers m ON m.ModifierId = tm.ModifierId JOIN DynamicModifiers dm ON dm.ModifierType = m.ModifierType
  WHERE dm.EffectType = 'EFFECT_PLAYER_REVEAL_CULTURE_TREE' AND i.Base IN (SELECT TraitType FROM Traits) AND (EXISTS (SELECT 1 FROM LShufResultCivPieces) OR (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_OFF'
      OR (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF' OR (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF');
INSERT OR IGNORE INTO TraitModifiers (TraitType, ModifierId) SELECT Base, ModifierId FROM LShufWork_CivReveal;
DELETE FROM TraitModifiers WHERE EXISTS (SELECT 1 FROM LShufWork_CivReveal v
  WHERE v.Ability = TraitModifiers.TraitType AND v.ModifierId = TraitModifiers.ModifierId);
-- An ability's own modifiers that ask for the civ's base trait (MOD_CIV_WONDER_PRODUCTION_<CIV>) ask for the ability
-- trait instead, so they follow the ability wherever it goes (CONTRACTS 14).
UPDATE RequirementArguments SET Value = Value || '_ABILITY'
  WHERE Name = 'TraitType' AND Value IN (SELECT Base FROM LShufWork_CivInfo) AND Value || '_ABILITY' IN (SELECT TraitType FROM Traits)
    AND RequirementId IN (SELECT rsr.RequirementId FROM RequirementSetRequirements rsr JOIN Modifiers m
      ON m.SubjectRequirementSetId = rsr.RequirementSetId OR m.OwnerRequirementSetId = rsr.RequirementSetId
      JOIN TraitModifiers tm ON tm.ModifierId = m.ModifierId WHERE tm.TraitType = RequirementArguments.Value || '_ABILITY');
-- Civilization abilities = Split (CONTRACTS 19): the copy path for every civ holding pieces.
CREATE TABLE IF NOT EXISTS LShufWork_CivCopy (Receiver TEXT, ModifierId TEXT, PRIMARY KEY (Receiver, ModifierId));
DELETE FROM LShufWork_CivCopy;
INSERT OR IGNORE INTO LShufWork_CivCopy (Receiver, ModifierId)
  SELECT r.CivilizationType, mm.ModifierId FROM LShufResultCivPieces r JOIN (SELECT PieceId, ModifierId, Role FROM LShufCivMappingModifiers
      UNION SELECT PieceId, ModifierId, Role FROM LShufCivMappingAgeModifiers) mm ON mm.PieceId = r.PieceId
  WHERE r.Kind = 'bullet' AND mm.Role IN ('effect', 'hidden')
    AND mm.ModifierId IN (SELECT tm.ModifierId FROM TraitModifiers tm WHERE tm.TraitType = (SELECT i.Ability FROM LShufWork_CivInfo i WHERE i.Civ = r.FromCivilization));
INSERT OR IGNORE INTO LShufWork_CivCopy (Receiver, ModifierId)
  SELECT r.CivilizationType, tm.ModifierId FROM LShufResultCivPieces r JOIN LShufWork_CivInfo i ON i.Civ = r.CivilizationType
  JOIN TraitModifiers tm ON tm.TraitType = i.Ability
  WHERE r.Kind = 'remainder' AND tm.ModifierId NOT IN (SELECT mm.ModifierId FROM (SELECT PieceId, ModifierId, Role FROM LShufCivMappingModifiers
      UNION SELECT PieceId, ModifierId, Role FROM LShufCivMappingAgeModifiers) mm JOIN LShufCivMapping m ON m.PieceId = mm.PieceId
      WHERE m.CivilizationType = r.CivilizationType AND m.Kind = 'bullet' AND m.Movable = 1 AND m.Age = i.Age
    AND m.PieceId NOT IN (SELECT d.PieceId FROM LShufCivPieceDead d WHERE d.Age = (SELECT Value FROM LShufOptions WHERE Name = 'Age')));
DELETE FROM LShufWork_CivCopy WHERE ModifierId NOT IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'TRAIT_LSHUF_CIVA_' || Civ, 'KIND_TRAIT' FROM LShufWork_CivInfo WHERE Civ IN (SELECT DISTINCT CivilizationType FROM LShufResultCivPieces WHERE Kind IN ('bullet', 'remainder'));
INSERT OR IGNORE INTO Traits (TraitType, Name, Description, InternalOnly)
  SELECT 'TRAIT_LSHUF_CIVA_' || i.Civ, i.AbilityName, 'LOC_LSHUF_TRAIT_CIV_DEALT_DESCRIPTION', 1 FROM LShufWork_CivInfo i
  WHERE i.Civ IN (SELECT DISTINCT CivilizationType FROM LShufResultCivPieces WHERE Kind IN ('bullet', 'remainder')) AND 'TRAIT_LSHUF_CIVA_' || i.Civ IN (SELECT Type FROM Types);
UPDATE CivilizationTraits SET TraitType = 'TRAIT_LSHUF_CIVA_' || CivilizationType
  WHERE CivilizationType IN (SELECT DISTINCT CivilizationType FROM LShufResultCivPieces WHERE Kind IN ('bullet', 'remainder')) AND TraitType = (SELECT i.Ability FROM LShufWork_CivInfo i WHERE i.Civ = CivilizationTraits.CivilizationType)
    AND 'TRAIT_LSHUF_CIVA_' || CivilizationType IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO Modifiers (ModifierId, ModifierType, NewOnly, OwnerRequirementSetId, OwnerStackLimit, Permanent, RunOnce,
    SubjectRequirementSetId, SubjectStackLimit)
  SELECT 'LSHUF_' || c.Receiver || '__' || m.ModifierId, m.ModifierType, m.NewOnly, m.OwnerRequirementSetId, m.OwnerStackLimit, m.Permanent, m.RunOnce,
    m.SubjectRequirementSetId, m.SubjectStackLimit FROM LShufWork_CivCopy c JOIN Modifiers m ON m.ModifierId = c.ModifierId;
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Extra, SecondExtra, Type, Value)
  SELECT 'LSHUF_' || c.Receiver || '__' || a.ModifierId, a.Name, a.Extra, a.SecondExtra, a.Type, a.Value
  FROM LShufWork_CivCopy c JOIN ModifierArguments a ON a.ModifierId = c.ModifierId
  WHERE 'LSHUF_' || c.Receiver || '__' || a.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO ModifierStrings (Context, ModifierId, Text)
  SELECT s.Context, 'LSHUF_' || c.Receiver || '__' || s.ModifierId, s.Text FROM LShufWork_CivCopy c JOIN ModifierStrings s ON s.ModifierId = c.ModifierId
  WHERE 'LSHUF_' || c.Receiver || '__' || s.ModifierId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType)
  SELECT 'LSHUF_' || c.Receiver || '__' || c.ModifierId, 'TRAIT_LSHUF_CIVA_' || c.Receiver FROM LShufWork_CivCopy c
  WHERE 'LSHUF_' || c.Receiver || '__' || c.ModifierId IN (SELECT ModifierId FROM Modifiers) AND 'TRAIT_LSHUF_CIVA_' || c.Receiver IN (SELECT TraitType FROM Traits);
UPDATE RequirementArguments SET Value = 'TRAIT_LSHUF_CIVA_' || (SELECT i.Civ FROM LShufWork_CivInfo i WHERE i.Ability = RequirementArguments.Value)
  WHERE Name = 'TraitType' AND Value IN (SELECT i.Ability FROM LShufWork_CivInfo i WHERE i.Civ IN (SELECT DISTINCT CivilizationType FROM LShufResultCivPieces WHERE Kind IN ('bullet', 'remainder')))
    AND RequirementId IN (SELECT rsr.RequirementId FROM RequirementSetRequirements rsr JOIN Modifiers m
      ON m.SubjectRequirementSetId = rsr.RequirementSetId OR m.OwnerRequirementSetId = rsr.RequirementSetId
      JOIN TraitModifiers tm ON tm.ModifierId = m.ModifierId WHERE tm.TraitType = RequirementArguments.Value);

-- Bound modifiers (CONTRACTS 23 R4): a unique's own rules go wherever the unique went.
CREATE TABLE IF NOT EXISTS LShufWork_Bound (ModifierId TEXT PRIMARY KEY, Trait TEXT);
DELETE FROM LShufWork_Bound;
INSERT OR IGNORE INTO LShufWork_Bound (ModifierId, Trait) SELECT b.ModifierId, COALESCE(
    (SELECT u.TraitType FROM Units u WHERE u.UnitType = b.AnchorType),
    (SELECT x.TraitType FROM Buildings x WHERE x.ConstructibleType = b.AnchorType),
    (SELECT q.TraitType FROM UniqueQuarters q WHERE q.UniqueQuarterType = b.AnchorType))
  FROM LShufBoundModifiers b WHERE b.ModifierId IN (SELECT ModifierId FROM Modifiers)
    AND (b.ByPiece IS NULL OR b.ByPiece NOT IN (SELECT PieceId FROM LShufResultCivPieces WHERE Kind = 'bullet'))
    AND (EXISTS (SELECT 1 FROM LShufResultCivPieces) OR (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_OFF' OR (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF'
      OR (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF');
DELETE FROM LShufWork_Bound WHERE Trait IS NULL OR Trait NOT IN (SELECT TraitType FROM Traits);
DELETE FROM TraitModifiers WHERE ModifierId IN (SELECT ModifierId FROM LShufWork_Bound)
  OR (ModifierId LIKE 'LSHUF\_%' ESCAPE '\' AND EXISTS (SELECT 1 FROM LShufWork_Bound b
    WHERE substr(TraitModifiers.ModifierId, -(length(b.ModifierId) + 2)) = '__' || b.ModifierId));
INSERT OR IGNORE INTO TraitModifiers (ModifierId, TraitType) SELECT ModifierId, Trait FROM LShufWork_Bound;

-- Favored-wonder pieces (CONTRACTS 31).
CREATE TABLE IF NOT EXISTS LShufWork_Wonder (ModifierId TEXT PRIMARY KEY, Civ TEXT, Wonder TEXT, Pct TEXT, NewId TEXT);
DELETE FROM LShufWork_Wonder;
INSERT OR IGNORE INTO LShufWork_Wonder (ModifierId, Civ, Wonder, Pct, NewId)
  SELECT mm.ModifierId, m.CivilizationType, fw.FavoredWonderType, a.Value, 'LSHUF_WONDER__' || m.CivilizationType
  FROM LShufCivMappingModifiers mm JOIN LShufCivMapping m ON m.PieceId = mm.PieceId
  JOIN Modifiers mo ON mo.ModifierId = mm.ModifierId
  JOIN DynamicModifiers d ON d.ModifierType = mo.ModifierType AND d.EffectType = 'EFFECT_CITY_ADJUST_FAVORED_WONDER_PRODUCTION'
  JOIN CivilizationFavoredWonders fw ON fw.CivilizationType = m.CivilizationType
  JOIN ModifierArguments a ON a.ModifierId = mm.ModifierId AND a.Name = 'Percent'
  WHERE fw.FavoredWonderType IN (SELECT ConstructibleType FROM Constructibles) AND (EXISTS (SELECT 1 FROM LShufResultCivPieces) OR (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_OFF'
      OR (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF' OR (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF');
INSERT OR IGNORE INTO Types (Type, Kind) SELECT 'LSHUF_WONDER_PRODUCTION_TYPE', 'KIND_MODIFIER' WHERE EXISTS (SELECT 1 FROM LShufWork_Wonder);
INSERT OR IGNORE INTO DynamicModifiers (ModifierType, CollectionType, EffectType)
  SELECT 'LSHUF_WONDER_PRODUCTION_TYPE', 'COLLECTION_PLAYER_CITIES', 'EFFECT_CITY_ADJUST_CONSTRUCTIBLE_PRODUCTION' WHERE 'LSHUF_WONDER_PRODUCTION_TYPE' IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO Modifiers (ModifierId, ModifierType)
  SELECT NewId, 'LSHUF_WONDER_PRODUCTION_TYPE' FROM LShufWork_Wonder WHERE 'LSHUF_WONDER_PRODUCTION_TYPE' IN (SELECT ModifierType FROM DynamicModifiers);
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Value)
  SELECT NewId, 'ConstructibleType', Wonder FROM LShufWork_Wonder WHERE NewId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Value)
  SELECT NewId, 'Percent', Pct FROM LShufWork_Wonder WHERE NewId IN (SELECT ModifierId FROM Modifiers);
INSERT OR IGNORE INTO TraitModifiers (TraitType, ModifierId)
  SELECT tm.TraitType, w.NewId FROM TraitModifiers tm JOIN LShufWork_Wonder w ON (tm.ModifierId = w.ModifierId OR (tm.ModifierId LIKE 'LSHUF\_%' ESCAPE '\'
      AND substr(tm.ModifierId, -(length(w.ModifierId) + 2)) = '__' || w.ModifierId))
  WHERE w.NewId IN (SELECT ModifierId FROM Modifiers);
DELETE FROM TraitModifiers WHERE EXISTS (SELECT 1 FROM LShufWork_Wonder w WHERE w.NewId IN (SELECT ModifierId FROM Modifiers)
  AND (TraitModifiers.ModifierId = w.ModifierId OR (TraitModifiers.ModifierId LIKE 'LSHUF\_%' ESCAPE '\'
      AND substr(TraitModifiers.ModifierId, -(length(w.ModifierId) + 2)) = '__' || w.ModifierId)));

-- Rule pieces (CONTRACTS 31).
CREATE TABLE IF NOT EXISTS LShufWork_Rule (PieceId TEXT PRIMARY KEY, Marker TEXT, Holder TEXT);
DELETE FROM LShufWork_Rule;
INSERT OR IGNORE INTO LShufWork_Rule (PieceId, Marker, Holder)
  SELECT DISTINCT p.PieceId, 'TRAIT_LSHUF_RULE_' || p.PieceId,
    CASE WHEN (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_OFF' THEN NULL ELSE COALESCE(
      (SELECT r.CivilizationType FROM LShufResultCivPieces r WHERE r.PieceId = p.PieceId AND r.Kind = 'bullet'),
      (SELECT r.CivilizationType FROM LShufResultCivPieces r WHERE r.Kind = 'ability' AND r.FromCivilization = m.CivilizationType),
      m.CivilizationType) END
  FROM LShufCivRulePieces p JOIN LShufCivMapping m ON m.PieceId = p.PieceId
  WHERE p.HomeTrait IN (SELECT TraitType FROM Traits) AND (EXISTS (SELECT 1 FROM LShufResultCivPieces) OR (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_OFF'
      OR (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_OFF' OR (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_OFF');
INSERT OR IGNORE INTO Types (Type, Kind) SELECT Marker, 'KIND_TRAIT' FROM LShufWork_Rule;
INSERT OR IGNORE INTO Traits (TraitType, InternalOnly) SELECT Marker, 1 FROM LShufWork_Rule WHERE Marker IN (SELECT Type FROM Types);
INSERT OR IGNORE INTO CivilizationTraits (CivilizationType, TraitType) SELECT Holder, Marker FROM LShufWork_Rule
  WHERE Holder IN (SELECT CivilizationType FROM Civilizations) AND Marker IN (SELECT TraitType FROM Traits);
UPDATE ProgressionTreeNodeUnlocks SET NotTraitType = (SELECT w.Marker FROM LShufWork_Rule w JOIN LShufCivRulePieces p ON p.PieceId = w.PieceId
    WHERE p.TargetModifier = ProgressionTreeNodeUnlocks.TargetType AND p.HomeTrait = ProgressionTreeNodeUnlocks.NotTraitType AND w.Marker IN (SELECT TraitType FROM Traits))
  WHERE (SELECT w.Marker FROM LShufWork_Rule w JOIN LShufCivRulePieces p ON p.PieceId = w.PieceId
    WHERE p.TargetModifier = ProgressionTreeNodeUnlocks.TargetType AND p.HomeTrait = ProgressionTreeNodeUnlocks.NotTraitType AND w.Marker IN (SELECT TraitType FROM Traits)) IS NOT NULL;
UPDATE RequirementArguments SET Value = (SELECT w.Marker FROM LShufWork_Rule w JOIN LShufCivRulePieces p ON p.PieceId = w.PieceId
    JOIN Modifiers mo ON mo.ModifierId = p.TargetModifier
    JOIN RequirementSetRequirements rsr ON rsr.RequirementSetId IN (mo.SubjectRequirementSetId, mo.OwnerRequirementSetId)
    WHERE rsr.RequirementId = RequirementArguments.RequirementId AND p.HomeTrait = RequirementArguments.Value
      AND w.Marker IN (SELECT TraitType FROM Traits) LIMIT 1)
  WHERE Name = 'TraitType' AND EXISTS (SELECT 1 FROM LShufWork_Rule w JOIN LShufCivRulePieces p ON p.PieceId = w.PieceId
    JOIN Modifiers mo ON mo.ModifierId = p.TargetModifier
    JOIN RequirementSetRequirements rsr ON rsr.RequirementSetId IN (mo.SubjectRequirementSetId, mo.OwnerRequirementSetId)
    WHERE rsr.RequirementId = RequirementArguments.RequirementId AND p.HomeTrait = RequirementArguments.Value
      AND w.Marker IN (SELECT TraitType FROM Traits));

-- Attribute tags (CONTRACTS 30).
CREATE TABLE IF NOT EXISTS LShufWork_CivTagOwn (Civ TEXT, Trait TEXT, PRIMARY KEY (Civ, Trait));
DELETE FROM LShufWork_CivTagOwn;
INSERT OR IGNORE INTO LShufWork_CivTagOwn (Civ, Trait) SELECT CivilizationType, TraitType FROM CivilizationTraits
  WHERE TraitType LIKE 'TRAIT\_ATTRIBUTE\_%' ESCAPE '\' AND CivilizationType IN (SELECT FromCivilization FROM LShufResultCivPieces WHERE Kind = 'tags'
    UNION SELECT CivilizationType FROM LShufResultCivPieces WHERE Kind = 'tags');
CREATE TABLE IF NOT EXISTS LShufWork_CivTagKind (Kind TEXT PRIMARY KEY);
DELETE FROM LShufWork_CivTagKind;
INSERT OR IGNORE INTO LShufWork_CivTagKind (Kind) VALUES ('CULTURAL'), ('ECONOMIC'), ('EXPANSIONIST'), ('MILITARISTIC'), ('POLITICAL'), ('SCIENTIFIC');
CREATE TABLE IF NOT EXISTS LShufWork_CivTagVar (Kind TEXT, Variant TEXT, PRIMARY KEY (Kind, Variant));
DELETE FROM LShufWork_CivTagVar;
INSERT OR IGNORE INTO LShufWork_CivTagVar (Kind, Variant) VALUES ('EXPANSIONIST', 'TALL'), ('EXPANSIONIST', 'WIDE'), ('POLITICAL', 'HAPPINESS'), ('POLITICAL', 'INFLUENCE');
-- The ages each receiver has Test of Time tags for, read before its rows go.
CREATE TABLE IF NOT EXISTS LShufWork_CivTagAge (Civ TEXT, Age TEXT, PRIMARY KEY (Civ, Age));
DELETE FROM LShufWork_CivTagAge;
INSERT OR IGNORE INTO LShufWork_CivTagAge (Civ, Age) SELECT DISTINCT o.Civ, substr(o.Trait, length('TRAIT_ATTRIBUTE_' || k.Kind || '_TOT_') + 1, 2)
  FROM LShufWork_CivTagOwn o JOIN LShufWork_CivTagKind k ON o.Trait LIKE 'TRAIT\_ATTRIBUTE\_' || k.Kind || '\_TOT\_%' ESCAPE '\'
  WHERE o.Civ IN (SELECT CivilizationType FROM LShufResultCivPieces WHERE Kind = 'tags');
DELETE FROM CivilizationTraits WHERE TraitType LIKE 'TRAIT\_ATTRIBUTE\_%' ESCAPE '\'
  AND CivilizationType IN (SELECT CivilizationType FROM LShufResultCivPieces WHERE Kind = 'tags');
-- The giver's plain tags.
INSERT OR IGNORE INTO CivilizationTraits (CivilizationType, TraitType)
  SELECT r.CivilizationType, o.Trait FROM LShufResultCivPieces r JOIN LShufWork_CivTagOwn o ON o.Civ = r.FromCivilization
  WHERE r.Kind = 'tags' AND o.Trait NOT LIKE '%\_TOT\_%' ESCAPE '\' AND r.CivilizationType IN (SELECT CivilizationType FROM Civilizations);
-- Test of Time tags for the receiver's ages, by the giver's kinds.
INSERT OR IGNORE INTO CivilizationTraits (CivilizationType, TraitType)
  SELECT r.CivilizationType, 'TRAIT_ATTRIBUTE_' || k.Kind || '_TOT_' || a.Age FROM LShufResultCivPieces r
  JOIN LShufWork_CivTagOwn o ON o.Civ = r.FromCivilization JOIN LShufWork_CivTagKind k ON o.Trait = 'TRAIT_ATTRIBUTE_' || k.Kind
  JOIN LShufWork_CivTagAge a ON a.Civ = r.CivilizationType
  WHERE r.Kind = 'tags' AND r.CivilizationType IN (SELECT CivilizationType FROM Civilizations)
    AND 'TRAIT_ATTRIBUTE_' || k.Kind || '_TOT_' || a.Age IN (SELECT TraitType FROM Traits);
INSERT OR IGNORE INTO CivilizationTraits (CivilizationType, TraitType)
  SELECT r.CivilizationType, 'TRAIT_ATTRIBUTE_' || v.Kind || '_TOT_' || a.Age || '_' || v.Variant FROM LShufResultCivPieces r
  JOIN LShufWork_CivTagVar v ON EXISTS (SELECT 1 FROM LShufWork_CivTagOwn o WHERE o.Civ = r.FromCivilization
      AND (o.Trait = 'TRAIT_ATTRIBUTE_' || v.Kind || '_' || v.Variant
        OR o.Trait LIKE 'TRAIT\_ATTRIBUTE\_' || v.Kind || '\_TOT\_%\_' || v.Variant ESCAPE '\'))
  JOIN LShufWork_CivTagAge a ON a.Civ = r.CivilizationType
  WHERE r.Kind = 'tags' AND r.CivilizationType IN (SELECT CivilizationType FROM Civilizations)
    AND 'TRAIT_ATTRIBUTE_' || v.Kind || '_TOT_' || a.Age || '_' || v.Variant IN (SELECT TraitType FROM Traits);
